<?php
require "conexao.php"; require "funcoes.php";
$patentes=$pdo->query("SELECT p.id_patente,p.nome_patente,p.salario,COUNT(s.id_soldado) AS total_soldados FROM patentes p LEFT JOIN soldados s ON s.id_patente=p.id_patente GROUP BY p.id_patente,p.nome_patente,p.salario ORDER BY p.nome_patente")->fetchAll();
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Patentes</title><link rel="stylesheet" href="estilo.css"></head><body><main class="container"><header><h1>Gerenciamento de patentes</h1><nav><a class="botao" href="cadastrar_patente.php">Cadastrar patente</a> <a class="botao secundario" href="listar.php">Ver soldados</a></nav></header><?php if(isset($_GET["sucesso"])): ?><p class="sucesso"><?= escapar($_GET["sucesso"]) ?></p><?php endif; ?><?php if($patentes): ?><div class="tabela-wrap"><table><thead><tr><th>Patente</th><th>Salário</th><th>Soldados</th><th>Ações</th></tr></thead><tbody><?php foreach($patentes as $p): ?><tr><td><?= escapar($p["nome_patente"]) ?></td><td>R$ <?= number_format((float)$p["salario"],2,',','.') ?></td><td><?= escapar($p["total_soldados"]) ?></td><td class="acoes"><a href="editar_patente.php?id=<?= escapar($p["id_patente"]) ?>">Editar</a><form action="excluir_patente.php" method="post" onsubmit="return confirm('Excluir esta patente? Os soldados vinculados ficarão sem patente e precisarão ser atualizados.')"><input type="hidden" name="id" value="<?= escapar($p["id_patente"]) ?>"><input type="hidden" name="token" value="<?= escapar($_SESSION["token"]) ?>"><button class="link-perigo" type="submit">Excluir</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>Nenhuma patente cadastrada.</p><?php endif; ?></main></body></html>
